import re
slugs = [l.strip()[:-3] for l in open('/Users/kristinarash/DEV/Flint/staging/_scope_supertraining_ch9d.txt') if l.strip()][:10]
cur = None
out = []
for line in open('/tmp/r9d/xdiff.txt'):
    if line.startswith('#####'):
        cur = line.strip(); out.append(cur); continue
    if not line.startswith('+'):
        continue
    txt = line[1:].strip()
    if 'Also in 9.2' in txt:
        out.append('  ALSO: ' + txt)
        continue
    for s in slugs:
        for m in re.finditer(re.escape(s), txt):
            a = max(0, m.start() - 5); b = min(len(txt), m.end() + 140)
            out.append('  LINK: ...' + txt[a:b])
    for m in re.finditer(r'PDF 5(7[4-9]|8\d)', txt):
        if 'Also in 9.2' in txt: break
        a = max(0, m.start() - 250); b = min(len(txt), m.end() + 30)
        out.append('  PDF: ...' + txt[a:b])
print('\n'.join(out))

