import re, os, glob
D = '/Users/kristinarash/DEV/Flint/staging/library/strength-and-conditioning/supertraining--verkhoshansky/'
names = [l.strip() for l in open('/Users/kristinarash/DEV/Flint/staging/_scope_supertraining_ch9d.txt') if l.strip()]
stems = set()
for root in ['/Users/kristinarash/DEV/Flint/staging/library', '/Users/kristinarash/SecondBrain']:
    for p in glob.glob(root + '/**/*.md', recursive=True):
        stems.add(os.path.basename(p)[:-3])
        rel = os.path.relpath(p, root)[:-3]
        stems.add(rel)
        parts = rel.split('/')
        for i in range(len(parts)):
            stems.add('/'.join(parts[i:]))
total = 0; bad = []
for n in names:
    t = open(D + n).read()
    body = t.split('---', 2)[2]
    if '—' in body.replace('** —', ''):
        # em dash outside heading labels
        for ln in body.splitlines():
            s = re.sub(r'^\*\*[^*]+\*\* —', '', ln)
            if '—' in s:
                print('EMDASH', n, s[:80])
    for m in re.findall(r'\[\[([^\]|#]+)', t):
        total += 1
        if m.strip() not in stems:
            bad.append((n, m))
print('links', total, 'bad', bad)
# heading label check new 10
for n in names[:10]:
    t = open(D + n).read()
    for lab in ['What it is', 'Why it works', 'When to apply', 'When NOT to apply', 'Example']:
        if ('**%s** —' % lab) not in t:
            print('MISSING LABEL', n, lab)
    if re.search(r'\*\*[^*]+:\*\*', t):
        print('COLON-IN-BOLD', n)

